  async function ensureAsignador(){if(!isAdmin())return null;try{const st=await rpc('control_auto_cupos_asignador_estado_v1');if(Number(st?.observaciones||0)>=1600)return st;const z=await rpc('control_auto_cupos_asignador_import_v1',{p_rows:ASIGNADOR_ROWS});return z}catch(e){console.warn('Asignador import',e);return {error:e.message||String(e)}}}
  window.v94ControlCuposATTT=async function(){
    if(!isAdmin()&&!(typeof window.rymHasModule==='function'&&window.rymHasModule('control_auto.cupos_attt')))return;
    window.__v75ControlMode=true;document.body.classList.remove('v70-portal','v70-admin');document.body.classList.add('v70-control');if(typeof window.v75ControlUnits==='function')await window.v75ControlUnits();
    const nav=document.querySelector('.side .nav');let nb=nav?.querySelector('[data-v94-control="cupos"]');if(nb)nav.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===nb));const top=document.querySelector('.top h1');if(top)top.textContent='Cupos ATTT';const v=document.querySelector('#view');if(!v)return;v.innerHTML='<div class="card">Conciliando Control de Auto + Asignador + eCarCheck...</div>';
    const imported=await ensureAsignador();
    try{const d=await rpc('control_auto_cupos_attt_v2',{p_limit:5000}),rows=d?.rows||[],k=d?.kpis||{};
      const srcCount=x=>rows.filter(r=>r[x]).length,states=[...new Set(rows.map(r=>r.estado).filter(Boolean))].sort(),recons=[...new Set(rows.map(r=>r.conciliacion).filter(Boolean))].sort();
      v.innerHTML=`<div class="v94-cupos"><section class="v94-cupos-hero"><div><h2>Cupos ATTT</h2><p>Las tres fuentes trabajan de la mano: <b>Control de Auto</b> conserva la historia interna, <b>Asignador</b> respalda el inventario/stock y <b>eCarCheck</b> confirma la asignación oficial actual. Un cupo que aparece solo en eCarCheck <b>no se considera nuestro</b>.</p></div><span class="v94-master-badge">Conciliación patrimonial</span></section>${imported?.error?`<div class="alert">No se pudo incorporar el Excel del asignador: ${E(imported.error)}</div>`:`<div class="v96-import-note">Excel Asignador · Global VIP 31-07-2026: ${E(imported?.cupos_unicos||'1644')} cupos únicos · fuente preservada sin sobreescribir eCarCheck.</div>`}<div class="v94-cupos-kpis"><article class="v94-cupo-kpi"><span>Inventario maestro</span><strong>${k.total||0}</strong></article><article class="v94-cupo-kpi good"><span>Propiedad grupo</span><strong>${k.propiedad_grupo||0}</strong></article><article class="v94-cupo-kpi"><span>Asignados</span><strong>${k.asignados||0}</strong></article><article class="v94-cupo-kpi"><span>Stock</span><strong>${k.stock||0}</strong></article><article class="v94-cupo-kpi warn"><span>Revisar</span><strong>${k.revisar||0}</strong></article><article class="v94-cupo-kpi bad"><span>eCarCheck externos</span><strong>${k.ecarcheck_externos||0}</strong></article></div><section class="v94-cupos-source"><article class="v94-source-card"><span>Control de Auto / Sheets</span><b>${srcCount('fuente_control')}</b><small>Historia y operación interna.</small></article><article class="v94-source-card"><span>Excel Asignador</span><b>${srcCount('fuente_asignador')}</b><small>Inventario administrativo y posible stock.</small></article><article class="v94-source-card"><span>eCarCheck ATTT</span><b>${srcCount('fuente_ecarcheck')}</b><small>Realidad oficial de asignación actual.</small></article><article class="v94-source-card"><span>Referencia ATTT</span><b>${srcCount('fuente_attt')}</b><small>Soporte documental adicional.</small></article></section><section class="v94-cupos-tools"><div class="v94-wide"><label>Buscar</label><input id="v96CQ" placeholder="Cupo, unidad, placa, empresa o titular"></div><div><label>Estado</label><select id="v96CE"><option value="">Todos</option>${states.map(x=>`<option>${E(x)}</option>`).join('')}</select></div><div><label>Conciliación</label><select id="v96CR"><option value="">Todas</option>${recons.map(x=>`<option>${E(x)}</option>`).join('')}</select></div><div><label>Propiedad</label><select id="v96CP"><option value="">Todos</option><option value="SI">Del grupo</option><option value="NO">No acreditado</option></select></div><div><label>Fuente</label><select id="v96CS"><option value="">Todas</option><option value="ASIGNADOR">Asignador</option><option value="CONTROL">Control</option><option value="ECAR">eCarCheck</option></select></div></section><div id="v96CCount" class="v94-cupos-count"></div><section id="v96COut" class="v94-cupos-table"></section></div>`;
      const q=v.querySelector('#v96CQ'),es=v.querySelector('#v96CE'),rs=v.querySelector('#v96CR'),ps=v.querySelector('#v96CP'),ss=v.querySelector('#v96CS'),co=v.querySelector('#v96CCount'),out=v.querySelector('#v96COut');
      const paint=()=>{const qq=N(q.value),a=rows.filter(r=>(!qq||N([r.numero_cupo,r.unidad,r.placa_unica,r.empresa,r.galera,r.propietario_ecarcheck,r.asignador_unidad,r.asignador_placa,r.asignador_empresa].join(' ')).includes(qq))&&(!es.value||r.estado===es.value)&&(!rs.value||r.conciliacion===rs.value)&&(!ps.value||(ps.value==='SI'&&r.propiedad_grupo)||(ps.value==='NO'&&!r.propiedad_grupo))&&(!ss.value||(ss.value==='ASIGNADOR'&&r.fuente_asignador)||(ss.value==='CONTROL'&&r.fuente_control)||(ss.value==='ECAR'&&r.fuente_ecarcheck)));co.textContent=`${a.length} de ${rows.length} cupos`;out.innerHTML=`<div class="table-wrap"><table class="pretty"><thead><tr><th>Cupo</th><th>Propiedad</th><th>Estado</th><th>Conciliación</th><th>Control Auto</th><th>Asignador</th><th>eCarCheck</th><th>Empresa / Titular</th></tr></thead><tbody>${a.map(r=>`<tr><td data-label="Cupo"><span class="v94-cupo-num">${E(r.numero_cupo)}</span><div class="v96-mini">${E(r.tipo_cupo||'')}</div></td><td data-label="Propiedad"><span class="${r.propiedad_grupo?'v96-property-yes':'v96-property-no'}">${r.propiedad_grupo?'GRUPO':'NO ACREDITADO'}</span></td><td data-label="Estado"><span class="v94-status ${E(r.estado)}">${E(r.estado)}</span></td><td data-label="Conciliación"><b>${E(r.conciliacion||'')}</b></td><td data-label="Control Auto">${E(r.unidad||'—')} · ${E(r.placa_unica||'—')}<div class="v96-mini">${E(r.cupo_control||'')}</div></td><td data-label="Asignador">${E(r.asignador_unidad||'—')} · ${E(r.asignador_placa||'—')}<div class="v96-mini">${E(r.asignador_estado||'')} · ${E(r.asignador_empresa||'')}</div></td><td data-label="eCarCheck">${E(r.cupo_ecarcheck||'—')}<div class="v96-mini">${E(fmt(r.ecarcheck_actualizado_at))}</div></td><td data-label="Empresa / Titular">${E(r.empresa||'—')}<div class="v96-mini">ATTT: ${E(r.propietario_ecarcheck||'—')}</div></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Sin resultados.</td></tr>'}</tbody></table></div>`};[es,rs,ps,ss].forEach(x=>x.onchange=paint);q.oninput=paint;paint();
    }catch(e){v.innerHTML=`<div class="alert">${E(e.message||e)}</div>`}
  };

