  if(typeof reportes==='function'&&!window.__v96Reports){const old=reportes;window.__v96Reports=true;reportes=async function(v){await old(v);const b=v.querySelector('#rBajas,#repBajas');if(b)b.onclick=()=>{state.active='bajas_panapass';shell();render()}}}
